import re

def solve(env, goal):
    # Parse goal: two <object> into/on <receptacle>
    g = goal.lower()
    m = re.search(r"(?:find|put|place|move|get|locate)\s+(?:two|2)\s+(.+?)\s+(?:in|on|into|onto)\s+(?:a|an|the)?\s*(.+?)(?:\.|$)", g)
    if not m:
        m = re.search(r"(?:two|2)\s+(.+?)\s+(?:in|on|into|onto)\s+(?:a|an|the)?\s*(.+?)(?:\.|$)", g)
    if not m:
        return
    obj_type = m.group(1).strip().rstrip(".")
    rec_type = m.group(2).strip().rstrip(".")
    obj_type = re.sub(r"^(a|an|the)\s+", "", obj_type)
    rec_type = re.sub(r"^(a|an|the)\s+", "", rec_type)

    def norm(s):
        return s.lower().strip()

    obj_t = norm(obj_type)
    rec_t = norm(rec_type)

    def words(s):
        return re.findall(r"[a-z0-9]+", s.lower())

    def matches_type(name, t):
        # name like "creditcard 2"; t like "creditcard"
        base = re.sub(r"\s+\d+$", "", name.strip().lower())
        return base == t or base.startswith(t + " ") or base == t

    def obj_id(name):
        return name.strip().lower()

    def find_objects_in_obs(obs):
        # return list of object ids of target type visible in observation
        found = []
        for w in re.finditer(r"\b((?:[a-z][a-z0-9]*)(?:\s+[a-z][a-z0-9]*)*\s+\d+)\b", obs.lower()):
            cand = w.group(1)
            if matches_type(cand, obj_t):
                found.append(cand)
        # also handle "In it, you see a creditcard 2" etc - covered by regex above
        return found

    def find_recs_in_obs(obs):
        recs = []
        for w in re.finditer(r"\b((?:[a-z][a-z0-9]*)(?:\s+[a-z][a-z0-9]*)*\s+\d+)\b", obs.lower()):
            cand = w.group(1)
            if matches_type(cand, rec_t):
                recs.append(cand)
        return recs

    def parse_inventory(obs):
        mm = re.search(r"you are carrying:\s*(.*)", obs.lower())
        if not mm:
            return []
        s = mm.group(1).strip().rstrip(".")
        if not s or s == "nothing":
            return []
        return [x.strip() for x in s.split(",") if x.strip()]

    def is_closed(obs, rec):
        return re.search(re.escape(rec) + r"\s+is\s+closed", obs.lower()) is not None

    def is_open(obs, rec):
        return re.search(re.escape(rec) + r"\s+is\s+open", obs.lower()) is not None

    def at(obs, rec):
        return re.search(r"you arrive at\s+" + re.escape(rec), obs.lower()) is not None or \
               re.search(r"you are facing the\s+" + re.escape(rec), obs.lower()) is not None

    # state
    holding = []
    placed = []
    opened = set()
    visited = set()
    current = None

    def step(cmd):
        nonlocal current
        r = env.step(cmd)
        return r

    # Initial observation
    obs = env.observation
    # Try to gather receptacle list from room description
    def all_receptacles(obs_text):
        recs = []
        for w in re.finditer(r"\b((?:[a-z][a-z0-9]*)(?:\s+[a-z][a-z0-9]*)*\s+\d+)\b", obs_text.lower()):
            cand = w.group(1)
            if cand in recs:
                continue
            recs.append(cand)
        return recs

    room_recs = all_receptacles(obs)

    def admissible():
        try:
            return env.admissible()
        except Exception:
            return []

    def do(cmd):
        adm = admissible()
        if adm and cmd not in adm:
            # try to still execute; but prefer valid
            r = env.step(cmd)
            return r
        return env.step(cmd)

    # Main loop: explore receptacles until two target objects found and moved to target receptacle
    # Get target receptacle id from room recs or by going to it
    target_rec = None
    for r in room_recs:
        if matches_type(r, rec_t):
            target_rec = r
            break
    if target_rec is None:
        # fallback: use name+1 guesses via admissible go to
        for cmd in admissible():
            mc = re.match(r"go to (.+)", cmd.lower())
            if mc and matches_type(mc.group(1), rec_t):
                target_rec = mc.group(1)
                break
    if target_rec is None:
        return

    # Ensure target open if closed
    def ensure_at(rec):
        nonlocal current
        if current == rec:
            return True
        r = do("go to " + rec)
        if "you arrive at" in r.lower() or "you are facing" in r.lower():
            current = rec
            return True
        return False

    def ensure_open(rec):
        if rec in opened:
            return True
        r = do("open " + rec)
        if "is open" in r.lower() or "you open" in r.lower():
            opened.add(rec)
            return True
        return False

    # Gather candidates from receptacles
    found = {}  # obj -> location
    to_take = []

    # First, scan room description for already visible objects
    for o in find_objects_in_obs(obs):
        found[o] = None  # unknown location, but present in room? Actually room desc may not list contents
    # The room desc lists receptacles, not items. So scan by visiting.

    # Strategy: visit each receptacle, open if closed, look at contents, take target objects
    # We need at most 2 target objects. Stop early once both placed.

    # Build ordered list of receptacles to visit
    recs = list(room_recs)
    # Ensure target rec included
    if target_rec not in recs:
        recs.append(target_rec)

    # Remove target from exploration order (we'll go there to place)
    order = [r for r in recs if r != target_rec]

    # Also try admissible go-to targets not in room description (rare)
    for cmd in admissible():
        mc = re.match(r"go to (.+)", cmd.lower())
        if mc:
            r = mc.group(1)
            if r not in recs and matches_type(r, rec_t):
                pass

    # Track objects we have seen that are target type and their location
    seen = {}  # obj -> rec
    placed_count = 0
    holding_obj = None

    # Helper to hold a target object
    def take_obj(o, loc):
        nonlocal current, holding_obj
        if current != loc:
            if not ensure_at(loc):
                return False
        r = do("take " + o + " from " + loc)
        if "you pick up" in r.lower() or "you take" in r.lower():
            holding_obj = o
            return True
        return False

    def place_holding():
        nonlocal holding_obj, placed_count, current
        if holding_obj is None:
            return True
        if current != target_rec:
            if not ensure_at(target_rec):
                return False
        if is_closed(env.observation, target_rec):
            if not ensure_open(target_rec):
                return False
        r = do("move " + holding_obj + " to " + target_rec)
        if "you move" in r.lower():
            placed_count += 1
            holding_obj = None
            return True
        return False

    # First check inventory (in case already holding)
    inv = parse_inventory(env.observation)
    for o in inv:
        if matches_type(o, obj_t):
            holding_obj = o
            break
    if holding_obj:
        place_holding()

    # Explore receptacles
    for rec in order:
        if placed_count >= 2:
            break
        if not ensure_at(rec):
            continue
        # open if closed
        if is_closed(env.observation, rec):
            ensure_open(rec)
        obs_now = env.observation
        # find target objects in this receptacle
        cands = []
        for w in re.finditer(r"\b((?:[a-z][a-z0-9]*)(?:\s+[a-z][a-z0-9]*)*\s+\d+)\b", obs_now.lower()):
            cand = w.group(1)
            if matches_type(cand, obj_t) and cand not in seen:
                cands.append(cand)
        for o in cands:
            if placed_count >= 2:
                break
            if holding_obj is not None:
                if not place_holding():
                    break
            if o not in seen:
                seen[o] = rec
                if take_obj(o, rec):
                    place_holding()
        # close? not necessary

    # If holding leftover, place
    if holding_obj is not None:
        place_holding()

    # If still need more, revisit all receptacles (maybe objects appeared)
    if placed_count < 2:
        # second pass
        for rec in order:
            if placed_count >= 2:
                break
            if not ensure_at(rec):
                continue
            if is_closed(env.observation, rec):
                ensure_open(rec)
            obs_now = env.observation
            for w in re.finditer(r"\b((?:[a-z][a-z0-9]*)(?:\s+[a-z][a-z0-9]*)*\s+\d+)\b", obs_now.lower()):
                cand = w.group(1)
                if matches_type(cand, obj_t) and cand not in seen:
                    seen[cand] = rec
                    if holding_obj is not None:
                        if not place_holding():
                            break
                    if take_obj(cand, rec):
                        place_holding()
                    if placed_count >= 2:
                        break
        if holding_obj is not None:
            place_holding()

    # Final attempt: check inventory and place
    inv = parse_inventory(env.observation)
    for o in inv:
        if matches_type(o, obj_t):
            holding_obj = o
            place_holding()
            break
