    if not m:
        return
    obj_t = re.sub(r"^(a|an|the)\s+", "", m.group(1).strip().rstrip(".")).strip().lower()
    rec_t = re.sub(r"^(a|an|the)\s+", "", m.group(2).strip().rstrip(".")).strip().lower()

    ART = {"a", "an", "the"}

    def clean(name):
        toks = name.strip().lower().split()
        while toks and toks[0] in ART:
            toks.pop(0)
        return " ".join(toks)

    def matches_type(name, t):
        base = re.sub(r"\s+\d+$", "", clean(name))
        return base == t

    def extract_names(text):
        out = []
        for w in re.finditer(r"\b([a-z][a-z0-9]*(?:\s+[a-z][a-z0-9]*){0,2}\s+\d+)\b", text.lower()):
            cand = clean(w.group(1))
            if cand:
                out.append(cand)
        return out

    def parse_inventory(obs):
        mm = re.search(r"you are carrying:\s*(.*)", obs.lower())
        if not mm:
            return []
        s = mm.group(1).strip().rstrip(".")
        if not s or s == "nothing":
            return []
        return [clean(p) for p in s.split(",") if p.strip()]

    def is_closed(obs, rec):
        return re.search(re.escape(rec) + r"\s+is\s+closed", obs.lower()) is not None

    obs = env.observation
    room_recs = extract_names(obs)

    target_rec = None
    for r in room_recs:
        if matches_type(r, rec_t):
            target_rec = r
            break
    if target_rec is None:
        for cmd in env.admissible():
            mc = re.match(r"go to (.+)", cmd.lower())
            if mc:
                cand = clean(mc.group(1))
                if matches_type(cand, rec_t):
                    target_rec = cand
                    break
    if target_rec is None:
        for cmd in env.admissible():
            mc = re.match(r"go to (.+)", cmd.lower())
            if mc:
                target_rec = clean(mc.group(1))
                break
    if target_rec is None:
        return

    current = None
    opened = set()
    seen = {}
    holding = None
    placed = 0

    def ensure_at(rec):
        nonlocal current
        if current == rec:
            return True
        r = env.step("go to " + rec)
        if "you arrive at" in r.lower() or "you are facing" in r.lower():
            current = rec
            return True
        return False

    def ensure_open(rec):
        if rec in opened:
            return True
        r = env.step("open " + rec)
        if "is open" in r.lower() or "you open" in r.lower():
            opened.add(rec)
            return True
        return False

    def take_obj(o, loc):
        nonlocal current, holding
        if current != loc:
            if not ensure_at(loc):
                return False
        r = env.step("take " + o + " from " + loc)
        if "you pick up" in r.lower() or "you take" in r.lower():
            holding = o
            return True
        return False

    def place_holding():
        nonlocal holding, placed, current
        if holding is None:
            return True
        if current != target_rec:
            if not ensure_at(target_rec):
                return False
        if is_closed(env.observation, target_rec):
            if not ensure_open(target_rec):
                return False
        r = env.step("move " + holding + " to " + target_rec)
        if "you move" in r.lower():
            placed += 1
            holding = None
            return True
        return False

    # pick up already-held
    for o in parse_inventory(env.observation):
        if matches_type(o, obj_t):
            holding = o
            break
    if holding:
        place_holding()

    if target_rec not in room_recs:
        room_recs.append(target_rec)
    order = [r for r in room_recs if r != target_rec]

    def scan_and_take(rec):
        # returns True if any placed/taken
        nonlocal holding, placed
        if not ensure_at(rec):
            return False
        if is_closed(env.observation, rec):
            if not ensure_open(rec):
                return False
        for cand in extract_names(env.observation):
            if placed >= 2:
                return True
            if not matches_type(cand, obj_t):
