            if cand in seen:
                continue
            seen[cand] = rec
            if holding is not None:
                if not place_holding():
                    return False
            if take_obj(cand, rec):
                place_holding()
        return True

    for rec in order:
        if placed >= 2:
            break
        scan_and_take(rec)

    if placed < 2:
        for rec in order:
            if placed >= 2:
